COPY public._radreply_audit (id, username, attribute, deleted_at, pid, query) FROM stdin;
1	benard	Mikrotik-Group	2026-06-25 08:43:02.030393+00	2764512	DELETE FROM radreply rr\nUSING (\n  SELECT DISTINCT username FROM radreply\n  WHERE username NOT LIKE 'K%@%' AND username NOT LIKE 'K%'\n) sub\nLEFT JOIN pppoe_subscribers ps\n  ON ps.username = sub.username AND ps.status IN ('active')\nWHERE rr.username = sub.username\n  AND ps.id IS NULL;
\.
